  const toRow=r=>[KQStages.names[c.block],c.title,r?.label||'暂无计入项',r?.count??0,c.denominator,c.denominator?((r?.ratio??0)*100).toFixed(1)+'%':'',c.unit,result.paper_count,c.covered_papers,c.uncovered_paper_ids.length,c.registered_materials??'',(r?.curriculum_notes||[]).join('；'),r?.legacy_formal_occurrence_ids.length??0,r?.supplemental_occurrence_ids.length??0,detail,c.unregistered_materials?.length??''];
